declare module "*.c" {
    const source: string
    export default source
}
declare module "*.py" {
    const source: string
    export default source
}
declare module "*.html" {
    const source: string
    export default source
}

declare module "x11" {
    const x11: any
    export default x11
}

declare module "*.svg" {
    const source: string
    export default source
}
